// Chat-template token removal (AIR-290): before the quarantine model reads untrusted text, every control token of that model's chat
// template is removed from it. Forged template markup raised attack success on open models in the research, and nothing shows that
// the serving stack leaves such strings in message content as plain text, so the harness assumes it parses them. The lists are data
// (config/chat-tokens.json, generated by scripts/chat-tokens.ts from each model's own tokenizer files), never typed here.
// Tokens are removed, not escaped, so no replacement text can form a token; the pass repeats until nothing is removed because the
// removal can join the text on both sides into a new token.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const DEFAULT_FILE = fileURLToPath(new URL('../../config/chat-tokens.json', import.meta.url));

/** The model has no usable chat-token list. The message is exactly `NoChatTokens: <model>`. */
export class NoChatTokens extends Error {
  constructor(readonly model: string) {
    super(`NoChatTokens: ${model.slice(0, 80)}`);
    this.name = 'NoChatTokens';
  }
}

/** The token list of one model, read from the file at call time. Throws NoChatTokens for a missing entry, an empty list or an empty token. */
export function loadChatTokens(model: string, file: string = DEFAULT_FILE): readonly string[] {
  let entry: unknown;
  try {
    const parsed: unknown = JSON.parse(readFileSync(file, 'utf8'));
    entry = typeof parsed === 'object' && parsed !== null && Object.hasOwn(parsed, model) ? (parsed as Record<string, unknown>)[model] : undefined;
  } catch {
    throw new NoChatTokens(model);
  }
  const tokens = typeof entry === 'object' && entry !== null ? (entry as { tokens?: unknown }).tokens : undefined;
  if (!Array.isArray(tokens) || tokens.length === 0 || !tokens.every((t) => typeof t === 'string' && t.length > 0)) throw new NoChatTokens(model);
  return Object.freeze([...(tokens as string[])]);
}

/** The removal did not settle within the pass cap: the text is dropped, never passed on unstripped. */
export class ChatTokensUnstable extends Error {
  constructor(readonly model: string) {
    super(`ChatTokensUnstable: ${model.slice(0, 80)}`);
    this.name = 'ChatTokensUnstable';
  }
}

export const MAX_PASSES = 16;

/** Text length that is safe to hand to neutralize: the longest token times a few beyond the cut the caller applies afterwards. */
export const marginOf = (tokens: readonly string[]): number => 4 * tokens.reduce((n, t) => Math.max(n, t.length), 0);

/** neutralize with a list already loaded. NFKC first, so compatibility forms (fullwidth and the like) that normalize into a token
 *  downstream are removed too; then removal to a fixed point, at most MAX_PASSES passes that remove something. */
export function neutralizeWith(tokens: readonly string[], text: string, model: string): { text: string; removed: number } {
  const ordered = [...tokens].sort((a, b) => b.length - a.length);
  let out = text;
  let removed = 0;
  for (let pass = 0; ; pass++) {
    const normalized = out.normalize('NFKC');
    const before = removed;
    out = normalized;
    for (const token of ordered) {
      const parts = out.split(token);
      if (parts.length > 1) {
        removed += parts.length - 1;
        out = parts.join('');
      }
    }
    if (removed === before) return { text: out, removed };
    if (pass + 1 >= MAX_PASSES) throw new ChatTokensUnstable(model);
  }
}

/** Removes every occurrence of every token of the model's list, to a fixed point. `removed` counts every removal. */
export function neutralize(text: string, model: string, file?: string): { text: string; removed: number } {
  return neutralizeWith(loadChatTokens(model, file), text, model);
}
